  const { sessionId, recipientToken, requestMetadata } = opts;

  const session = await loadCscSession(sessionId);

  if (!session) {
    throw new AppError(AppErrorCode.NOT_FOUND, {
      message: `CSC session "${sessionId}" not found.`,
